<?php require __DIR__.'/../config/config.php';require_role('admin');$pdo=db();
function crud_page($title,$table,$field){global $pdo;if($_SERVER['REQUEST_METHOD']==='POST'){ $v=trim($_POST['value']??''); if($v!==''){$q=$pdo->prepare("INSERT INTO `$table`(`$field`) VALUES(?)");$q->execute([$v]);}}$rows=$pdo->query("SELECT * FROM `$table` ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container section"><a href="./">← لوحة المدير</a><div class="card" style="margin-top:15px"><h1><?=e($title)?></h1><form method="post" style="display:flex;gap:10px"><input class="field" style="margin:0;flex:1;padding:13px;border:1px solid #e4eaf2;border-radius:11px" name="value" placeholder="أضف جديدًا" required><button class="btn">إضافة</button></form></div><div class="card" style="margin-top:15px"><table class="table"><tr><th>#</th><th>الاسم</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r[$field])?></td></tr><?php endforeach;?></table></div></main></body></html><?php }
